registros.texto:
"generated": {
  "type": "array",
  "items": {
    "type": "object",
    "required": ["path"],
    "additionalProperties": false,
    "properties": {

"seed": {
  "oneOf": [
    { "type": "null" },
    { "type": "integer" },
    { "type": "string", "minLength": 1 }

"version": {
  "type": "string",
  "const": "1.0"

"overlays": {
  "type": "array",
  "items": {
    "type": "object",
    "required": [
      "id", "shot_id", "content",
      "font", "size", "weight", "color",
      "position", "enter", "exit"
    "additionalProperties": false,
    "properties": {

"id": {
  "type": "string",
  "pattern": "^text_[0-9]{2,3}$"

"font": {
  "type": "string",
  "description": "Must reference a font defined in brand-lock typography."

"size": {
  "type": "string",
  "enum": ["display", "headline", "body", "caption"]

"weight": {
  "type": "string",
  "enum": ["regular", "medium", "bold", "black"]

"enter": {
  "type": "object",
  "required": ["at", "animation"],
  "additionalProperties": false,
  "properties": {

"animation": {
  "type": "string",
  "enum": ["fade-in", "slide-up", "slide-down", "type-on", "hard-cut"]

"exit": {
  "type": "object",
  "required": ["at", "animation"],
  "additionalProperties": false,
  "properties": {

"animation": {
  "type": "string",
  "enum": ["fade-out", "slide-up", "slide-down", "hard-cut"]

"operator": {
  "oneOf": [
    { "type": "null" },
    { "type": "string", "minLength": 1 }
  "description": "Who started the run. Free text: a name, a handle, or a CI job id. Null when nobody recorded it."

"text_overlays_ref": {
  "oneOf": [
    { "type": "null" },
    { "type": "string", "minLength": 1 }
  "description": "Null for a storyboard with no on-screen text."

"text_overlays_sha256": {
  "oneOf": [
    { "type": "null" },
    { "type": "string", "pattern": "^[0-9a-f]{64}$" }

"brand_lock_configured": {
  "type": "boolean",
  "description": "False when the snapshot is an unfilled template. tools/validate_brand_lock.py --require-configured is what decides this."

"generators": {
  "type": "array",
  "description": "Generators targeted by this run, with the model version current at run time. The capability matrix records what is current now; this records what was current then.",
  "items": {
    "type": "object",
    "required": ["id", "model_version"],
    "additionalProperties": false,
    "properties": {

"rounds": {
  "type": "array",
  "description": "Appended once per revision round. Each round records the prompt files it produced. Frames and critiques are found on disk under frames/round-N/ and critiques/round-N/, not listed here, so two operators working the same round never write the same JSON.",
  "items": {
    "type": "object",
    "required": ["round", "started_at", "prompts"],
    "additionalProperties": false,
    "properties": {

"prompts": {
  "type": "array",
  "minItems": 1,
  "items": {
    "type": "object",
    "required": ["generator", "ref", "sha256"],
    "additionalProperties": false,
    "properties": {

"run_id": {
  "oneOf": [
    { "type": "null" },
    { "type": "string", "pattern": "^[0-9]{8}T[0-9]{6}Z-[0-9a-f]{8}$" }
  "description": "The run this critique belongs to. Matches run.json:run_id. Format: UTC compact timestamp, a dash, then 8 hex characters."

"round": {
  "oneOf": [
    { "type": "null" },
    { "type": "integer", "minimum": 1 }
  "description": "Revision round, 1-indexed. Round 1 is the first generation pass."

"shot_id": {
  "oneOf": [
    { "type": "null" },
    { "type": "string", "pattern": "^shot_[0-9]{2,3}$" }
  "description": "Shot this frame was generated for. Null when critiquing a standalone image with no storyboard."

"brand_lock_ref": {
  "oneOf": [
    { "type": "null" },
    { "type": "string", "minLength": 1 }
  "description": "Path to the brand-lock.snapshot.md the frame was judged against, relative to the output directory root. Null when no brand-lock was available, which caps confidence at MEDIUM."

"brand_lock_sha256": {
  "oneOf": [
    { "type": "null" },
    { "type": "string", "pattern": "^[0-9a-f]{64}$" }
  "description": "SHA-256 of the brand-lock file as read. Null only when brand_lock_ref is null."

"image_ref": {
  "oneOf": [
    { "type": "null" },
    { "type": "string", "minLength": 1 }
  "description": "Path to the frame that was critiqued, relative to the output directory root."

"image_sha256": {
  "oneOf": [
    { "type": "null" },
    { "type": "string", "pattern": "^[0-9a-f]{64}$" }
  "description": "SHA-256 of the frame bytes as reviewed. This is what makes the verdict falsifiable: if the file at image_ref no longer hashes to this value, the verdict does not describe it."

"prompt_ref": {
  "oneOf": [
    { "type": "null" },
    { "type": "string", "minLength": 1 }
  "description": "Path to the prompt file the frame was generated from, relative to the output directory root. Null when the prompt is unknown, which caps confidence at MEDIUM."

"prompt_sha256": {
  "oneOf": [
    { "type": "null" },
    { "type": "string", "pattern": "^[0-9a-f]{64}$" }
  "description": "SHA-256 of the prompt file. Null only when prompt_ref is null."

"generator": {
  "oneOf": [
    { "type": "null" },
    { "type": "string", "pattern": "^[a-z0-9][a-z0-9-]*$" }
  "description": "Generator id that produced the frame. Must match an id in visual-prompt-forge/adapters/_capabilities.json. Null when unknown."

"model_version": {
  "oneOf": [
    { "type": "null" },
    { "type": "string", "minLength": 1 }
  "description": "Model version string as of generation, copied from the capability matrix entry. The matrix records what is current; this records what ran."

"seed": {
  "oneOf": [
    { "type": "null" },
    { "type": "integer" },
    { "type": "string", "minLength": 1 }
  "description": "Generation seed if the generator exposes one. Null when it does not."

"verdict": {
  "type": "string",
  "enum": ["ACCEPT", "REVISE", "REJECT"]

"confidence": {
  "type": "string",
  "enum": ["HIGH", "MEDIUM", "LOW"]

"working": {
  "type": "array",
  "description": "Concrete positives. Observations, not flattery.",
  "items": { "type": "string", "minLength": 1 }

"issues": {
  "type": "array",
  "items": {
    "type": "object",
    "required": ["layer", "severity", "note", "fix_type", "fix"],
    "additionalProperties": false,
    "properties": {

"layer": {
  "type": "string",
  "enum": ["Brand Lock", "Series Lock", "Shot Spec", "Composition", "Technical", "Continuity"]

"fix_type": {
  "type": "string",
  "enum": ["prompt-level", "post-level", "re-roll"]

"prompt_style": {
  "type": "string",
  "enum": ["keyword", "natural", "paragraph"]

"api_access": {
  "type": "string",
  "enum": ["full", "limited", "none"]
